# Keep original paper figures reproducible from the credited local source assets.
for m in c['media'].values():
 if m['type']=='image' and m['url'].startswith('assets/') and m.get('provenance',{}).get('assetSha256'):
  source=ROOT/'docs'/m['url']; provenance=m['provenance']
  assert hashlib.sha256(source.read_bytes()).hexdigest()==provenance['assetSha256'], f"Changed source figure: {source}"
  # Extracted figures are publishing inputs; the offline paper library is optional.
  # When present, still verify the pinned PDF. Clean checkouts need only the assets.
  paper=ROOT/provenance['paper']
  if paper.is_file():
   assert hashlib.sha256(paper.read_bytes()).hexdigest()==provenance['paperSha256'], f"Changed source paper: {paper}"
  shutil.copy(source,DIST/m['url'])
lines=['# 11 · Khảo sát phương pháp học từ dữ liệu đa nguồn','', '_Catalog gốc kiểm 02/10/2026; DataMIL/DAgger bổ sung 05/10; FOCA và training VLA/WM bổ sung 06/10/2026. Đây là kết quả/thiết kế của tác giả; không là kết quả của đội. P0/P1/P2 là ưu tiên MVP, không xếp hạng chất lượng công trình._','', '## Kết luận cho thiết kế','', 'Phân biệt origin, cách tạo, supervision và representation. Synthetic là cách tạo dữ liệu, không modality; latent là derived representation. Robot action-labeled trajectories học control; video action-free dùng objective riêng. MVP robot demonstrations được thu trong sim; hardware thật kiểm ở phase riêng. FluxVLA có sẵn nhiều năng lực platform/SDG/HITL; đóng góp của đội phải đo ở recipe, binding, mixture và hiệu quả theo task, không chỉ wrapper.','', 'Không đối chiếu success percentages giữa các paper như leaderboard: task, robot, splits và protocol khác nhau. HumanEgo có cấu hình robot-data-free; không nói mọi human-to-robot learning đều bắt buộc teleop. Thiết kế này chủ động dùng target-robot anchors trong sim cho MVP, không gọi chúng là real-robot recordings.','']
